#!/usr/bin/env python3
"""CI check: ensure that modified framework files have updated version markers.

Fails if any markdown file under .claude/skills/job-application-assistant/ is
modified in git without a change/bump to its 'framework_version' frontmatter key.
Also ensures all framework files have a valid 'framework_version' frontmatter key.
"""

from __future__ import annotations
import os
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SKILL_DIR = ROOT / ".claude/skills/job-application-assistant"
FRAMEWORK_FILES = sorted(SKILL_DIR.glob("*.md"))

# Add root AGENTS.md if it exists
root_agents = ROOT / "AGENTS.md"
if root_agents.exists():
    FRAMEWORK_FILES.append(root_agents)

def run_git(args: list[str]) -> tuple[int, str, str]:
    res = subprocess.run(["git"] + args, cwd=str(ROOT), capture_output=True, text=True)
    return res.returncode, res.stdout, res.stderr

def get_base_commit() -> str | None:
    # If in GitHub Actions PR, use the target branch's base ref
    base_ref = os.environ.get("GITHUB_BASE_REF")
    if base_ref:
        # Check if origin/base_ref is fetched
        rc, _, _ = run_git(["rev-parse", "--verify", f"origin/{base_ref}"])
        if rc == 0:
            return f"origin/{base_ref}"
        # Try without origin/
        rc, _, _ = run_git(["rev-parse", "--verify", base_ref])
        if rc == 0:
            return base_ref

    # If running in GitHub Actions but not a PR (e.g. push to master)
    if os.environ.get("GITHUB_ACTIONS"):
        rc, _, _ = run_git(["rev-parse", "--verify", "HEAD~1"])
        if rc == 0:
            return "HEAD~1"

    # Otherwise (running locally), check uncommitted changes against HEAD
    rc, _, _ = run_git(["rev-parse", "--verify", "HEAD"])
    if rc == 0:
        return "HEAD"

    return None

def parse_frontmatter(path: Path) -> dict:
    if not path.exists():
        return {}
    text = path.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        return {}
    end = text.find("\n---", 4)
    if end == -1:
        return {}

    # Simple parser for YAML/frontmatter
    data = {}
    for line in text[4:end].splitlines():
        if ":" in line:
            k, v = line.split(":", 1)
            data[k.strip()] = v.strip().strip('"').strip("'")
    return data

def has_non_trivial_changes(file_path: Path, base_commit: str) -> bool:
    # Get diff of the file from base_commit to HEAD
    rel_path = str(file_path.relative_to(ROOT))
    rc, stdout, stderr = run_git(["diff", "-U0", base_commit, "--", rel_path])
    if rc != 0:
        # If diff fails (e.g. file is new/untracked), it's a change
        return True

    # Parse diff lines
    # We want to count lines added/removed that:
    # - do not match framework_version line
    # - are not empty/whitespace only
    meaningful_changes = 0
    version_changed = False

    for line in stdout.splitlines():
        if line.startswith("+++") or line.startswith("---") or line.startswith("@@"):
            continue
        if line.startswith("+") or line.startswith("-"):
            content = line[1:].strip()
            if not content:
                continue
            if re.match(r"^framework_version\s*:", content):
                version_changed = True
                continue
            # Check if it's just frontmatter syntax (e.g. ---)
            if content == "---":
                continue
            meaningful_changes += 1

    # If the version key itself was modified, we don't fail, regardless of other changes
    if version_changed:
        return False

    # If there are meaningful changes but the version was not changed
    return meaningful_changes > 0

def main() -> int:
    errors = []

    # 1. Lint: Check that all framework files have framework_version in frontmatter
    for path in FRAMEWORK_FILES:
        rel_path = str(path.relative_to(ROOT))
        fm = parse_frontmatter(path)
        if "framework_version" not in fm:
            errors.append(f"{rel_path}: missing 'framework_version' in frontmatter")

    # 2. Check for missing version bumps in modified files
    base_commit = get_base_commit()
    if base_commit:
        print(f"Comparing HEAD against base commit: {base_commit}")
        for path in FRAMEWORK_FILES:
            rel_path = str(path.relative_to(ROOT))
            if "framework_version" not in parse_frontmatter(path):
                # Skip checking changes if it doesn't even have frontmatter (already reported above)
                continue
            if has_non_trivial_changes(path, base_commit):
                errors.append(
                    f"{rel_path}: modified without bumping 'framework_version'. "
                    f"Please update the version in the frontmatter."
                )
    else:
        print("No base commit found (e.g. initial commit or shallow clone without base branch). Skipping diff checks.")

    if errors:
        print("Framework Version Check Failed:")
        for err in errors:
            print(f"  - {err}")
        return 1

    print("Framework Version Check: OK")
    return 0

if __name__ == "__main__":
    sys.exit(main())

import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

/**
 * The shape of the fields we read out of a `package.json` while searching for
 * OpenWiki's own manifest. Everything is optional because we parse arbitrary
 * `package.json` files encountered while walking up the tree and only accept the
 * one that is actually OpenWiki's.
 */
interface OwnPackageJson {
  /**
   * The package name. Used to confirm a candidate manifest is OpenWiki's own
   * and not a parent/monorepo `package.json`.
   *
   * @default undefined — treated as "not OpenWiki's manifest", keep walking up.
   */
  name?: string;

  /**
   * The published semver string, the single source of truth surfaced as
   * {@link OPENWIKI_VERSION}.
   *
   * @default undefined — treated as "not a usable manifest", keep walking up.
   */
  version?: string;
}

/**
 * Fallback returned when no OpenWiki `package.json` can be found (should never
 * happen in a real install; guards against a corrupt or unexpected layout so a
 * version read never throws and never breaks a run).
 */
const UNKNOWN_VERSION = "0.0.0-unknown";

/**
 * Reads OpenWiki's own version from its `package.json` at module load, so the
 * runtime version can never drift from the published one. Starts at this
 * module's own location (`import.meta.url`) and walks up the directory tree,
 * accepting the first `package.json` whose `name` is `"openwiki"`. This works
 * from source (`src/version.ts`), from the built `dist/`, and from an installed
 * `node_modules/openwiki/dist/`, because every one of those sits below the
 * manifest we are looking for.
 */
function readOwnVersion(): string {
  let dir = path.dirname(fileURLToPath(import.meta.url));

  for (;;) {
    try {
      const pkg = JSON.parse(
        readFileSync(path.join(dir, "package.json"), "utf8"),
      ) as OwnPackageJson;

      if (pkg.name === "openwiki" && typeof pkg.version === "string") {
        return pkg.version;
      }
    } catch {
      // No readable/parseable package.json here; keep walking up.
    }

    const parent = path.dirname(dir);
    if (parent === dir) {
      return UNKNOWN_VERSION;
    }
    dir = parent;
  }
}

/**
 * OpenWiki's published version, derived at runtime from `package.json` so it
 * stays in lockstep with releases without a hardcoded constant to maintain.
 */
export const OPENWIKI_VERSION = readOwnVersion();

/**
 * OpenWiki's OKF producer actor, the `by` value stamped on code-owned
 * `generated` and `verified` events (OKF v0.2 §7 `<producer>/<version>`
 * convention). Every deterministic provenance and trust projection derives
 * from this single source so actor identity cannot drift.
 */
export const OPENWIKI_PRODUCER_ACTOR = `openwiki/${OPENWIKI_VERSION}`;

import {
  advanceObsoleteWatchSet,
  diffSurface,
  extractSurface,
  obsoleteTargetsFor,
} from "../benchmark/surface.js";
import type {
  CheckpointEvaluationRecord,
  CheckpointResult,
  EvaluationBackend,
  EvidenceCorpus,
  KnowledgeArtifact,
  LedgerCheckpoint,
  LedgerExecutionMetrics,
  ObsoleteFactTarget,
  SurfaceItem,
  SemanticEvidenceMap,
} from "../core/types.js";
import {
  computeClaimState,
  computeEvaluationCompleteness,
} from "../metrics/claims.js";
import { computeChurn } from "../metrics/churn.js";
import type { BenchmarkProgressReporter } from "./progress-events.js";

/**
 * Mutable state carried from one checkpoint to the next as the trace is walked.
 * Each evaluated checkpoint reads the previous checkpoint's carry and produces
 * the next one, so the sticky obsolete watch set and the temporal surface diff
 * stay correct across the whole run.
 */
export interface CheckpointCarry {
  /**
   * The artifact captured at the previous checkpoint, used to measure churn.
   *
   * @default undefined the first checkpoint has no prior artifact
   */
  previousArtifact: KnowledgeArtifact | undefined;

  /**
   * The previous checkpoint's id, used as the "from" side of the surface diff.
   *
   * @default undefined the first checkpoint has no inbound transition
   */
  previousCheckpointId: string | undefined;

  /**
   * The previous checkpoint's extracted surface, diffed against the current one
   * to detect transitions.
   *
   * @default undefined the first checkpoint has no prior surface
   */
  previousSurface: SurfaceItem[] | undefined;

  /**
   * Obsolete fact versions still under the forgetting watch set entering this
   * checkpoint. Sticky: a version stays until the requirements revive it.
   */
  outstandingObsolete: ObsoleteFactTarget[];
}

/**
 * The starting carry for the first checkpoint of a run: no prior artifact,
 * checkpoint, or surface, and empty fact-evaluation and obsolete-watch sets.
 *
 * @returns A fresh carry with every history field cleared.
 */
export function initialCarry(): CheckpointCarry {
  return {
    previousArtifact: undefined,
    previousCheckpointId: undefined,
    previousSurface: undefined,
    outstandingObsolete: [],
  };
}

/**
 * Everything one checkpoint evaluation needs. The artifact, evidence, and
 * efficiency are supplied by the caller because they are the only things that
 * differ between a live run (captured from the System Under Test) and a
 * re-evaluation (loaded from a saved run); everything else is identical.
 */
export interface EvaluateCheckpointInputs {
  /**
   * Absolute path to the benchmark's source repository, read at the checkpoint
   * commit to extract the scorable surface.
   */
  sourceRepoPath: string;

  /**
   * The checkpoint being evaluated (its id and commit are used).
   */
  checkpoint: LedgerCheckpoint;

  /**
   * Zero-based position of this checkpoint in the trace. Index 0 has no inbound
   * transition, so no surface diff or obsolete facts are produced for it.
   */
  index: number;

  /**
   * The immutable wiki artifact under evaluation at this checkpoint.
   */
  artifact: KnowledgeArtifact;

  /**
   * The source evidence (current and historical) grounding precision judgments.
   */
  evidence: EvidenceCorpus;

  /** Evaluator-only semantic topic-to-source routing metadata. */
  evidenceMap?: SemanticEvidenceMap;

  /**
   * The evaluation backend that produces the per-item verdicts.
   */
  evaluationBackend: EvaluationBackend;

  /**
   * The carry from the previous checkpoint.
   */
  carry: CheckpointCarry;

  /**
   * The System Under Test efficiency observations for this checkpoint, measured
   * live or copied from a saved run. Churn is recomputed here from the carry.
   */
  efficiency: LedgerExecutionMetrics;

  /**
   * Lifecycle observer for progress events.
   */
  reportProgress: BenchmarkProgressReporter;
}

/**
 * The outcome of evaluating one checkpoint: the measurements to record, history
 * entry to append, and the carry to pass to the next checkpoint.
 */
export interface EvaluatedCheckpoint {
  /**
   * The checkpoint measurements to append to the run result.
   */
  checkpointResult: CheckpointResult;

  /**
   * The evaluation record to push onto the run's history, feeding diagnostics.
   */
  history: CheckpointEvaluationRecord;

  /**
   * The carry to hand to the next checkpoint.
   */
  nextCarry: CheckpointCarry;
}

/**
 * Evaluate a single checkpoint: extract its source surface, diff it against the
 * previous checkpoint to derive transitions and newly obsolete versions, advance
 * the sticky forgetting watch set, run the evaluation backend, and reduce the raw
 * verdicts into current claim-state and evaluator-completeness measurements.
 * This is the loop body shared verbatim by the live runner and the
 * saved-run re-evaluator; the only per-caller differences (artifact/evidence
 * source and how efficiency is built) are passed in through the inputs.
 *
 * Sticky obsolete targets: once a version goes obsolete it stays in the watch set
 * for every later checkpoint, retired only when the requirements revive that
 * knowledge, so a version already judged forgotten is still re-checked later. That
 * is what lets the Stale-Knowledge Lifetime diagnostic measure how long stale
 * knowledge lingers.
 *
 * @param inputs - The checkpoint evaluation inputs.
 *
 * @returns The measurements, history entry, and next carry for this checkpoint.
 */
export async function evaluateCheckpoint(
  inputs: EvaluateCheckpointInputs,
): Promise<EvaluatedCheckpoint> {
  const {
    sourceRepoPath,
    checkpoint,
    index,
    artifact,
    evidence,
    evidenceMap,
    evaluationBackend,
    carry,
    efficiency,
    reportProgress,
  } = inputs;

  const surface = await extractSurface(sourceRepoPath, checkpoint.commit);

  let newlyObsolete: ObsoleteFactTarget[] = [];

  if (
    index > 0 &&
    carry.previousCheckpointId !== undefined &&
    carry.previousSurface !== undefined
  ) {
    newlyObsolete = obsoleteTargetsFor(
      diffSurface(
        carry.previousSurface,
        surface,
        carry.previousCheckpointId,
        checkpoint.id,
      ),
    );
  }

  const obsoleteFacts = advanceObsoleteWatchSet({
    outstanding: carry.outstandingObsolete,
    surface,
    newlyObsolete,
  });

  reportProgress({
    type: "evaluation-start",
    checkpointId: checkpoint.id,
    obsoleteFactCount: obsoleteFacts.length,
  });

  const evaluation = await evaluationBackend.evaluate(
    {
      artifact,
      evidence,
      evidenceMap,
      obsoleteFacts,
    },
    {
      onClaimExtractionProgress: (completed, total) =>
        reportProgress({
          type: "claim-extraction-progress",
          checkpointId: checkpoint.id,
          completed,
          total,
          obsoleteFactCount: obsoleteFacts.length,
        }),
      onClaimEvaluationProgress: (claimCount, completed, total) =>
        reportProgress({
          type: "claim-evaluation-progress",
          checkpointId: checkpoint.id,
          claimCount,
          completed,
          total,
          obsoleteFactCount: obsoleteFacts.length,
        }),
    },
  );

  const claims = computeClaimState(evaluation.precisionEvaluations);
  const currentClaims = evaluation.precisionEvaluations.filter(
    (item) => item.tense === "current",
  );
  const evaluationCompleteness = computeEvaluationCompleteness(
    evaluation.precisionEvaluations,
    evaluation.forgettingEvaluations,
    evaluation.warnings ?? [],
  );

  reportProgress({
    type: "checkpoint-complete",
    checkpointId: checkpoint.id,
    claimCount: claims.total,
    supportedCount: claims.supported,
    staleCount: claims.stale,
    hallucinatedCount: claims.invented,
    unverifiedCount: claims.unverified,
    supportedRate: claims.supportedRate,
    stalenessRate: claims.stalenessRate,
    hallucinationRate: claims.hallucinationRate,
    unverifiedRate: claims.unverifiedRate,
    forgottenCount: evaluation.forgettingEvaluations.filter(
      (item) => item.verdict === "forgotten",
    ).length,
    obsoleteFactCount: evaluation.forgettingEvaluations.length,
    evaluationCompleteness: evaluationCompleteness.rate,
    indeterminateCount: evaluationCompleteness.indeterminate,
    evaluationItemCount: evaluationCompleteness.total,
    staleClaims: currentClaims
      .filter((item) => item.verdict === "stale")
      .map(({ location, assertion }) => ({ location, assertion })),
    hallucinatedClaims: currentClaims
      .filter((item) => item.verdict === "invented")
      .map(({ location, assertion }) => ({ location, assertion })),
  });

  const checkpointResult: CheckpointResult = {
    checkpointId: checkpoint.id,
    claims,
    evaluationCompleteness,
    efficiency: {
      ...efficiency,
      churnedLines: computeChurn(carry.previousArtifact, artifact),
    },
    // Retain the raw verdicts, not just their reduced counts, so each claim state
    // and forgetting result remains explainable in the persisted result.
    evaluations: {
      precisionEvaluations: evaluation.precisionEvaluations,
      forgettingEvaluations: evaluation.forgettingEvaluations,
      warnings: evaluation.warnings ?? [],
    },
  };

  const history: CheckpointEvaluationRecord = {
    forgettingEvaluations: evaluation.forgettingEvaluations,
  };

  const nextCarry: CheckpointCarry = {
    // Keep every obsolete version under watch, including ones just judged
    // forgotten: LEDGER does not treat forgetting as permanent, so a version stays
    // in the forgetting pass until the requirements revive it (the revival filter
    // in advanceObsoleteWatchSet is the only way a target leaves the watch set).
    outstandingObsolete: obsoleteFacts,
    previousArtifact: artifact,
    previousCheckpointId: checkpoint.id,
    previousSurface: surface,
  };

  return { checkpointResult, history, nextCarry };
}

//! 增量游标代表已成功覆盖的窗口，失败的尝试不能把尚未读到的条目跳过去。
use super::sync_source;
use std::sync::Arc;
use uuid::Uuid;
use wiremock::{matchers::method, Mock, MockServer, Request, ResponseTemplate};

async fn retry_reads_the_uncovered_window(
    prior_success: bool,
    fail_before_retry: bool,
) -> anyhow::Result<()> {
    let Some(url) = utopia_store::test_db::url() else {
        return Ok(());
    };
    let pool = sqlx::PgPool::connect(&url).await?;
    let (org, ws, kb, source) = (
        Uuid::now_v7(),
        Uuid::now_v7(),
        Uuid::now_v7(),
        Uuid::now_v7(),
    );
    sqlx::query("INSERT INTO organizations(id,name) VALUES($1,'checkpoint-test')")
        .bind(org)
        .execute(&pool)
        .await?;
    sqlx::query("INSERT INTO workspaces(id,org_id,name) VALUES($1,$2,'checkpoint-test')")
        .bind(ws)
        .bind(org)
        .execute(&pool)
        .await?;
    sqlx::query(
        "INSERT INTO knowledge_bases(id,workspace_id,name) VALUES($1,$2,'checkpoint-test')",
    )
    .bind(kb)
    .bind(ws)
    .execute(&pool)
    .await?;
    let server = MockServer::start().await;
    sqlx::query(
        "INSERT INTO sources(id,kb_id,kind,name,config) VALUES($1,$2,'custom','fixture',$3)",
    )
    .bind(source)
    .bind(kb)
    .bind(serde_json::json!({"endpoint":server.uri()}))
    .execute(&pool)
    .await?;
    let started = chrono::Utc::now() - chrono::Duration::hours(2);
    let changed = started + chrono::Duration::minutes(30);
    if prior_success {
        let run = utopia_store::sources::start_run(&pool, source).await?;
        utopia_store::sources::finish_run(&pool, run, source, None, 0, 0).await?;
        sqlx::query("UPDATE source_sync_runs SET started_at=$2,finished_at=$3 WHERE id=$1")
            .bind(run)
            .bind(started)
            .bind(started + chrono::Duration::hours(1))
            .execute(&pool)
            .await?;
        utopia_store::sources::touch_sync_time(&pool, source, started + chrono::Duration::hours(1))
            .await?;
    }
    let dir = std::env::temp_dir().join(format!("utopia-checkpoint-{source}"));
    let cfg = utopia_core::config::AppConfig {
        data_dir: dir.to_string_lossy().into_owned(),
        ..Default::default()
    };
    let search = Arc::new(utopia_search::SearchIndex::open(&dir.join("search"))?);
    let state = crate::state::AppState::new(pool.clone(), &cfg, search, "test-only".into());
    let result = async {
        if fail_before_retry {
            Mock::given(method("GET")).respond_with(ResponseTemplate::new(503)).mount(&server).await;
            assert!(sync_source(&state, source).await.is_err());
            let failed = utopia_store::sources::get(&pool, source).await?;
            assert_eq!(failed.last_sync_status, "failed");
            assert!(failed.last_sync_at.is_some(), "attempt time still drives scheduling and diagnostics");
            server.reset().await;
        }
        // **把真正发出去的下界记下来**：只断言那条漏掉的更新回来了是不够的，
        // 假如下界根本没发（每次都全量拉），这个断言照样过，而增量就悄悄没了
        let asked: std::sync::Arc<std::sync::Mutex<Vec<Option<chrono::DateTime<chrono::Utc>>>>> =
            Default::default();
        let seen = asked.clone();
        Mock::given(method("GET")).respond_with(move |request: &Request| {
            let since = request.url.query_pairs().find(|(k,_)| k == "since")
                .map(|(_,v)| chrono::DateTime::parse_from_rfc3339(&v).unwrap().with_timezone(&chrono::Utc));
            seen.lock().unwrap().push(since);
            let items = if since.is_none_or(|s| s <= changed) {
                serde_json::json!([{"id":"missed", "title":"Missed update", "content":"An update from the uncovered window"}])
            } else { serde_json::json!([]) };
            ResponseTemplate::new(200).set_body_json(serde_json::json!({"items":items}))
        }).mount(&server).await;
        sync_source(&state, source).await?;
        let count: i64 = sqlx::query_scalar("SELECT count(*) FROM documents WHERE source_id=$1")
            .bind(source).fetch_one(&pool).await?;
        anyhow::ensure!(count == 1, "incremental cursor skipped an unimported update: {count} documents");
        let ok = utopia_store::sources::get(&pool, source).await?;
        assert_eq!(ok.last_sync_status, "ok");
        // 下界取自上一次**成功**那一轮的开始，不是上一次尝试的结束，也不是没有下界
        let asked = asked.lock().unwrap().clone();
        let last = asked.last().copied().flatten();
        if prior_success {
            let last = last.expect("没有带下界：增量拉取整个没了");
            assert!(
                (last - started).num_seconds().abs() <= 1,
                "下界应当是上一次成功那轮的开始 {started}，实得 {last}"
            );
            assert!(last < changed, "下界晚于那次改动，漏掉的窗口又被跳过了");
        } else {
            assert!(last.is_none(), "没有成功过的源不该带下界，实得 {last:?}");
        }
        Ok::<_, anyhow::Error>(())
    }.await;
    sqlx::query("DELETE FROM knowledge_bases WHERE id=$1")
        .bind(kb)
        .execute(&pool)
        .await?;
    sqlx::query("DELETE FROM organizations WHERE id=$1")
        .bind(org)
        .execute(&pool)
        .await?;
    drop(state);
    let _ = std::fs::remove_dir_all(dir);
    result
}

#[tokio::test]
async fn a_failed_first_sync_does_not_skip_the_existing_items() -> anyhow::Result<()> {
    retry_reads_the_uncovered_window(false, true).await
}

#[tokio::test]
async fn retry_keeps_updates_from_the_previous_successful_run_window() -> anyhow::Result<()> {
    retry_reads_the_uncovered_window(true, true).await
}

#[tokio::test]
async fn updates_during_a_successful_sync_remain_in_the_next_window() -> anyhow::Result<()> {
    retry_reads_the_uncovered_window(true, false).await
}

import { compareClocks } from './clock.js'

/**
 * Sort two entries as Last-Write-Wins (LWW).
 *
 * Last Write Wins is a conflict resolution strategy for sorting elements
 * where the element with a greater clock (latest) is chosen as the winner.
 *
 * @param {Entry} a First entry
 * @param {Entry} b Second entry
 * @return {number} 1 if a is latest, -1 if b is latest
 * @private
 */
function LastWriteWins (a, b) {
  // Ultimate conflict resolution (take the first/left arg)
  const First = (a, b) => a
  // Sort two entries by their clock id, if the same always take the first
  const sortById = (a, b) => SortByClockId(a, b, First)
  // Sort two entries by their clock time, if concurrent,
  // determine sorting using provided conflict resolution function
  const sortByEntryClocks = (a, b) => SortByClocks(a, b, sortById)
  // Sort entries by clock time as the primary sort criteria
  return sortByEntryClocks(a, b)
}

/**
 * Sort two entries by their clock time.
 * @param {Entry} a First entry to compare
 * @param {Entry} b Second entry to compare
 * @param {function(a, b)} resolveConflict A function to call if entries are
 * concurrent (happened at the same time). The function should take in two
 * entries and return 1 if the first entry should be chosen and -1 if the
 * second entry should be chosen.
 * @return {number} 1 if a is greater, -1 if b is greater
 * @private
 */
function SortByClocks (a, b, resolveConflict) {
  // Compare the clocks
  const diff = compareClocks(a.clock, b.clock)
  // If the clocks are concurrent, use the provided
  // conflict resolution function to determine which comes first
  return diff === 0 ? resolveConflict(a, b) : diff
}

/**
 * Sort two entries by their clock id.
 * @param {Entry} a First entry to compare
 * @param {Entry} b Second entry to compare
 * @param {function(a, b)} resolveConflict A function to call if the clocks ids
 * are the same. The function should take in two entries and return 1 if the
 * first entry should be chosen and -1 if the second entry should be chosen.
 * @return {number} 1 if a is greater, -1 if b is greater
 * @private
 */
function SortByClockId (a, b, resolveConflict) {
  // Sort by ID if clocks are concurrent,
  // take the entry with a "greater" clock id
  return a.clock.id === b.clock.id
    ? resolveConflict(a, b)
    : a.clock.id < b.clock.id ? -1 : 1
}

/**
 * A wrapper function to throw an error if the results of a passed function
 * return zero
 * @param {function(a, b)} [tiebreaker] The tiebreaker function to validate.
 * @return {function(a, b)} 1 if a is greater, -1 if b is greater
 * @throws {Error} if func ever returns 0
 * @private
 */
function NoZeroes (func) {
  const msg = `Your log's tiebreaker function, ${func.name}, has returned zero and therefore cannot be`

  const comparator = (a, b) => {
    // Validate by calling the function
    const result = func(a, b)
    if (result === 0) { throw Error(msg) }
    return result
  }

  return comparator
}

